return items.map((item, index) => {
  const j = item.json || {};
  const ahora = new Date();
  const ts = Date.now();

  const headers = Array.isArray(j.payload?.headers)
    ? j.payload.headers
    : [];

  const getHeader = (name) => {
    const h = headers.find(
      x => String(x.name || '').toLowerCase() === name.toLowerCase()
    );
    return h?.value || '';
  };

  const remitente =
    j.from ||
    j.From ||
    getHeader('From') ||
    '';

  const destinatario =
    j.to ||
    j.To ||
    getHeader('To') ||
    '';

  const asunto =
    j.subject ||
    j.Subject ||
    getHeader('Subject') ||
    '(Sin asunto)';

  let cuerpo =
    j.textPlain ||
    j.text ||
    j.snippet ||
    j.body ||
    '';

  // Si Gmail devuelve el mensaje completo y el texto no vino simplificado,
  // intentamos recuperar text/plain del payload.
  if (!cuerpo && Array.isArray(j.payload?.parts)) {
    const plain = j.payload.parts.find(p => p.mimeType === 'text/plain');
    if (plain?.body?.data) {
      try {
        cuerpo = Buffer
          .from(plain.body.data.replace(/-/g, '+').replace(/_/g, '/'), 'base64')
          .toString('utf8');
      } catch (e) {
        cuerpo = '';
      }
    }
  }

  if (!cuerpo && j.payload?.mimeType === 'text/plain' && j.payload?.body?.data) {
    try {
      cuerpo = Buffer
        .from(j.payload.body.data.replace(/-/g, '+').replace(/_/g, '/'), 'base64')
        .toString('utf8');
    } catch (e) {
      cuerpo = '';
    }
  }

  const labels = Array.isArray(j.labelIds)
    ? j.labelIds
    : Array.isArray(j.labels)
      ? j.labels.map(x => typeof x === 'string' ? x : x.id || x.name)
      : [];

  const origen_carpeta = labels.includes('SPAM') ? 'spam' : 'bandeja';

  const fechaCorreo = j.internalDate
    ? new Date(Number(j.internalDate))
    : ahora;

  return {
    json: {
      id_gmail: j.id || null,
      thread_id_gmail: j.threadId || null,

      id_ejecucion:
        'CLAS-SIN-' +
        ts +
        '-' +
        index +
        '-' +
        Math.random().toString(36).slice(2, 7),

      id_incidente:
        'INC-' +
        ts +
        '-' +
        index +
        '-' +
        Math.random().toString(36).slice(2, 7),

      flujo: '01',
      proceso: 'clasificador_correos',
      escenario: 'sin_seguridad',

      origen_carpeta,
      remitente,
      destinatario,
      asunto,
      cuerpo,

      // En correos reales la categoría real debe ser etiquetada
      // posteriormente por el evaluador.
      categoria_real: 'pendiente_validacion',

      hora_ingreso: fechaCorreo
        .toISOString()
        .slice(0, 19)
        .replace('T', ' ')
    },
    pairedItem: { item: index }
  };
});

return items.map(item => {
  const texto = `${item.json.asunto || ''} ${item.json.cuerpo || ''}`.toLowerCase();

  let categoria = 'legitimo';

  const palabrasPhishing = [
    'contraseña',
    'password',
    'urgente',
    'actualizar inmediatamente',
    'verifique su cuenta',
    'verificar su cuenta',
    'enlace',
    'credenciales',
    'cuenta será bloqueada',
    'cuenta sera bloqueada',
    'inicie sesión',
    'inicie sesion'
  ];

  const palabrasSpam = [
    'oferta',
    'promoción',
    'promocion',
    'gratis',
    'descuento',
    'premio',
    'ganador'
  ];

  if (palabrasPhishing.some(p => texto.includes(p))) {
    categoria = 'phishing';
  } else if (palabrasSpam.some(p => texto.includes(p))) {
    categoria = 'spam';
  }

  const deteccion = new Date();

  item.json.categoria_sistema = categoria;

  item.json.clasificacion_correcta =
    item.json.categoria_real === 'pendiente_validacion'
      ? null
      : categoria === item.json.categoria_real;

  item.json.hora_deteccion = deteccion
    .toISOString()
    .slice(0, 19)
    .replace('T', ' ');

  item.json.incidente = categoria !== 'legitimo';

  // Escenario SIN seguridad:
  // una amenaza puede ser detectada por reglas básicas,
  // pero no existe una respuesta automática SOAR.
  item.json.activo_comprometido = item.json.incidente;
  item.json.ejecucion_segura = !item.json.incidente;
  item.json.incidente_resuelto = !item.json.incidente;

  return item;
});
